// Shared contract for the native Nxeon mail client (/dashboard/mail).
// Both the IMAP/SMTP backend (lib/mail/*, lib/actions-mail.ts) and the UI
// (components/customer/mail/*, app/dashboard/mail) build against these types so
// they can't drift. The client connects to the customer's own mailbox on the
// self-hosted mail server (10.20.0.10) over IMAP (993) / SMTP submission (587),
// authenticating with the mailbox's stored (encrypted) credential.

export const MAIL_IMAP_HOST = process.env.MAIL_IMAP_HOST || "10.20.0.10";
export const MAIL_IMAP_PORT = Number(process.env.MAIL_IMAP_PORT || 993);
export const MAIL_SMTP_HOST = process.env.MAIL_SMTP_HOST || "10.20.0.10";
export const MAIL_SMTP_PORT = Number(process.env.MAIL_SMTP_PORT || 587);

export type MailFolderRole =
  | "inbox" | "sent" | "drafts" | "trash" | "junk" | "archive" | "custom";

export type MailFolder = {
  path: string; // IMAP path, e.g. "INBOX", "Sent"
  name: string; // display name
  role: MailFolderRole;
  unread: number;
  total: number;
};

export type MailAddress = { name?: string; address: string };

export type MessageSummary = {
  uid: number;
  folder: string;
  from: MailAddress;
  to: MailAddress[];
  subject: string;
  preview: string; // short text snippet of the body
  date: string; // ISO
  seen: boolean;
  flagged: boolean; // starred
  answered: boolean;
  hasAttachments: boolean;
};

export type MessageAttachment = {
  id: string; // opaque id for the download route (e.g. "<uid>:<partId>")
  filename: string;
  mime: string;
  sizeBytes: number;
};

export type MessageFull = MessageSummary & {
  cc: MailAddress[];
  html: string | null; // SANITIZED html body (must be sanitized server-side)
  text: string | null;
  attachments: MessageAttachment[];
};

export type MailboxInfo = {
  address: string;
  usedBytes: number;
  quotaBytes: number;
};

export type ListResult = {
  messages: MessageSummary[];
  total: number;
  page: number;
  pageSize: number;
};

/** A file to attach, carried from the composer to the SMTP send (transient — never stored). */
export type SendAttachment = {
  filename: string;
  contentType: string; // MIME type; server defaults to application/octet-stream
  contentBase64: string; // raw base64 (no "data:*;base64," prefix)
};

export type SendPayload = {
  to: string; // comma-separated
  cc?: string;
  bcc?: string;
  subject: string;
  text?: string;
  html?: string;
  inReplyToUid?: number; // for replies (sets In-Reply-To / References)
  replyFolder?: string; // folder of the message being replied to
  attachments?: SendAttachment[]; // transient file attachments (not persisted)
};

1	// Mailcow REST API client.
2	//
3	// Plain server-side module (NO "use server") — safe to import from server
4	// actions, route handlers, server components and the worker; never bundled to
5	// the client. Talks to a self-hosted Mailcow instance over its REST API.
6	//
7	// Configuration is read from the environment at call time (never hardcoded):
8	//   MAILCOW_API_URL  e.g. https://mail.nxeon.cloud/api/v1
9	//   MAILCOW_API_KEY  the X-API-Key value
10	//
11	// Every function throws a clear Error on a non-success response (including when
12	// Mailcow itself replies with a `{type:"danger"|"error"}` payload) or when the
13	// integration is not configured. Callers that must stay failure-tolerant (the
14	// order flow) wrap these in try/catch.
15	
16	export class MailcowError extends Error {
17	  constructor(
18	    message: string,
19	    public status?: number,
20	    public body?: unknown,
21	  ) {
22	    super(message);
23	    this.name = "MailcowError";
24	  }
25	}
26	
27	/** Both env vars present and non-empty. */
28	export function mailcowConfigured(): boolean {
29	  return Boolean(
30	    process.env.MAILCOW_API_URL?.trim() && process.env.MAILCOW_API_KEY?.trim(),
31	  );
32	}
33	
34	function config(): { base: string; key: string } {
35	  const base = process.env.MAILCOW_API_URL?.trim();
36	  const key = process.env.MAILCOW_API_KEY?.trim();
37	  if (!base || !key) {
38	    throw new MailcowError(
39	      "Mailcow not configured — set MAILCOW_API_URL and MAILCOW_API_KEY.",
40	    );
41	  }
42	  return { base: base.replace(/\/+$/, ""), key };
43	}
44	
45	/**
46	 * Core request helper. Performs a fetch to `${MAILCOW_API_URL}${path}` with the
47	 * X-API-Key header, parses the JSON body, and throws a MailcowError on any
48	 * non-2xx status or on a Mailcow error payload.
49	 */
50	async function mcRequest(
51	  method: "GET" | "POST",
52	  path: string,
53	  body?: unknown,
54	): Promise<unknown> {
55	  const { base, key } = config();
56	  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;
57	
58	  let res: Response;
59	  try {
60	    res = await fetch(url, {
61	      method,
62	      headers: {
63	        "X-API-Key": key,
64	        "Content-Type": "application/json",
65	        Accept: "application/json",
66	      },
67	      body: body === undefined ? undefined : JSON.stringify(body),
68	      cache: "no-store",
69	    });
70	  } catch (e) {
71	    throw new MailcowError(
72	      `Mailcow unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
73	    );
74	  }
75	
76	  const text = await res.text();
77	  let parsed: unknown = text;
78	  try {
79	    parsed = text ? JSON.parse(text) : null;
80	  } catch {
81	    // leave parsed as raw text
82	  }
83	
84	  if (!res.ok) {
85	    throw new MailcowError(
86	      `Mailcow ${method} ${path} -> HTTP ${res.status}`,
87	      res.status,
88	      parsed,
89	    );
90	  }
91	
92	  assertNoApiError(parsed, `${method} ${path}`);
93	  return parsed;
94	}
95	
96	/**
97	 * Mailcow POST endpoints return HTTP 200 even on logical failure, signalling the
98	 * outcome via `type` in the (array-wrapped) payload. Detect and surface those.
99	 */
100	function assertNoApiError(parsed: unknown, ctx: string): void {
101	  const entries = Array.isArray(parsed) ? parsed : [parsed];
102	  for (const entry of entries) {
103	    if (entry && typeof entry === "object" && "type" in entry) {
104	      const type = String((entry as { type: unknown }).type ?? "").toLowerCase();
105	      if (type === "danger" || type === "error") {
106	        const rawMsg = (entry as { msg?: unknown }).msg;
107	        const msg = Array.isArray(rawMsg) ? rawMsg.join(" ") : String(rawMsg ?? "unknown error");
108	        throw new MailcowError(`Mailcow ${ctx} failed: ${msg}`, undefined, parsed);
109	      }
110	    }
111	  }
112	}
113	
114	// ---------- Mutations ----------
115	
116	/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
117	 * which callers may ignore). */
118	export async function mcCreateDomain(domain: string): Promise<unknown> {
119	  return mcRequest("POST", "/add/domain", {
120	    domain,
121	    description: `nxeon ${domain}`,
122	    aliases: 400,
123	    mailboxes: 100,
124	    defquota: 1024,
125	    maxquota: 102400,
126	    quota: 102400,
127	    active: "1",
128	    restart_sogo: "0",
129	  });
130	}
131	
132	/** True if the domain already exists in Mailcow. */
133	export async function mcDomainExists(domain: string): Promise<boolean> {
134	  try {
135	    const res = await mcRequest("GET", `/get/domain/${encodeURIComponent(domain)}`);
136	    // Mailcow returns {} (or []) for an unknown domain, or the domain object.
137	    if (!res) return false;
138	    if (Array.isArray(res)) return res.length > 0;
139	    if (typeof res === "object") {
140	      return "domain_name" in res || "domain" in res;
141	    }
142	    return false;
143	  } catch {
144	    return false;
145	  }
146	}
147	
148	export async function mcCreateMailbox(opts: {
149	  localPart: string;
150	  domain: string;
151	  name: string;
152	  password: string;
153	  quotaMB: number;
154	}): Promise<unknown> {
155	  return mcRequest("POST", "/add/mailbox", {
156	    local_part: opts.localPart,
157	    domain: opts.domain,
158	    name: opts.name,
159	    password: opts.password,
160	    password2: opts.password,
161	    quota: opts.quotaMB,
162	    active: "1",
163	  });
164	}
165	
166	/** Activate / deactivate a mailbox (used for suspend/resume). */
167	export async function mcSetMailboxActive(address: string, active: boolean): Promise<unknown> {
168	  return mcRequest("POST", "/edit/mailbox", {
169	    items: [address],
170	    attr: { active: active ? "1" : "0" },
171	  });
172	}
173	
174	/**
175	 * Set a new password on an existing mailbox (customer-initiated reset). Mailcow
176	 * requires both `password` and `password2`; `force_pw_update:"0"` means the user
177	 * is not forced to change it on next webmail login (we just gave them this one).
178	 */
179	export async function mcSetMailboxPassword(address: string, password: string): Promise<unknown> {
180	  return mcRequest("POST", "/edit/mailbox", {
181	    items: [address],
182	    attr: { password, password2: password, force_pw_update: "0" },
183	  });
184	}
185	
186	/** Change a mailbox quota (MB). */
187	export async function mcSetQuota(address: string, quotaMB: number): Promise<unknown> {
188	  return mcRequest("POST", "/edit/mailbox", {
189	    items: [address],
190	    attr: { quota: quotaMB },
191	  });
192	}
193	
194	/** Delete a mailbox. */
195	export async function mcDeleteMailbox(address: string): Promise<unknown> {
196	  return mcRequest("POST", "/delete/mailbox", [address]);
197	}
198	
199	// ---------- Mailbox discovery (read-only) ----------
200	
201	/** A mailbox as it actually exists on Mailcow, narrowed to what we can adopt. */
202	export type MailcowMailbox = {
203	  address: string; // Mailcow's `username` — the full email address
204	  domain: string;
205	  name: string;
206	  active: boolean;
207	  quotaBytes: number;
208	  quotaUsedBytes: number;
209	};
210	
211	/**
212	 * List the mailboxes that really exist on a domain (`GET /get/mailbox/all/<domain>`).
213	 *
214	 * WHY this exists: `resolveMailbox` used to read only `db.mailbox`, so a mailbox
215	 * that lives on Mailcow without a local row was completely invisible in the
216	 * portal — the "it's not detecting the mailbox I already have on this account"
217	 * report. This is the read half of the reconciliation; the adoption half
218	 * (lib/mail/imap.ts `discoverMailboxes`) gates on domain verification.
219	 *
220	 * A domain Mailcow doesn't know returns `{}`, which we normalise to `[]`.
221	 */
222	export async function mcListMailboxes(domain: string): Promise<MailcowMailbox[]> {
223	  const res = await mcRequest("GET", `/get/mailbox/all/${encodeURIComponent(domain)}`);
224	  const rows = Array.isArray(res) ? res : [];
225	  const want = domain.trim().toLowerCase();
226	  const out: MailcowMailbox[] = [];
227	  for (const r of rows) {
228	    if (!r || typeof r !== "object") continue;
229	    const o = r as Record<string, unknown>;
230	    const address = typeof o.username === "string" ? o.username.trim().toLowerCase() : "";
231	    if (!address.includes("@")) continue;
232	    const mboxDomain =
233	      typeof o.domain === "string" ? o.domain.trim().toLowerCase() : address.slice(address.lastIndexOf("@") + 1);
234	    // Never return a row for a different domain than the one asked for — the
235	    // caller uses the domain to decide ownership, so it must not be spoofable
236	    // by a surprising API response shape.
237	    if (mboxDomain !== want) continue;
238	    out.push({
239	      address,
240	      domain: mboxDomain,
241	      name: typeof o.name === "string" ? o.name : "",
242	      active: toActive(o.active),
243	      quotaBytes: Number(o.quota) > 0 ? Number(o.quota) : 0,
244	      quotaUsedBytes: Number(o.quota_used) > 0 ? Number(o.quota_used) : 0,
245	    });
246	  }
247	  return out;
248	}
249	
250	// ---------- Aliases ----------
251	
252	/** A mail alias as returned by Mailcow, narrowed to the fields the UI needs. */
253	export type MailcowAlias = {
254	  id: number;
255	  address: string; // the alias address (what mail is sent to)
256	  goto: string; // destination(s), comma-separated
257	  active: boolean;
258	  domain?: string;
259	};
260	
261	/** Coerce Mailcow's mixed number/string `active` flag to a boolean. */
262	function toActive(v: unknown): boolean {
263	  return v === 1 || v === "1" || v === true;
264	}
265	
266	/**
267	 * List all aliases configured on a domain (`GET /get/alias/all/<domain>`).
268	 * Mailcow returns an array of alias objects; a domain with no aliases yields an
269	 * empty array (or `{}`), which we normalise to `[]`.
270	 */
271	export async function mcListAliases(domain: string): Promise<MailcowAlias[]> {
272	  const res = await mcRequest("GET", `/get/alias/all/${encodeURIComponent(domain)}`);
273	  const rows = Array.isArray(res) ? res : [];
274	  const out: MailcowAlias[] = [];
275	  for (const r of rows) {
276	    if (!r || typeof r !== "object") continue;
277	    const o = r as Record<string, unknown>;
278	    const id = Number(o.id);
279	    const address = typeof o.address === "string" ? o.address : "";
280	    if (!Number.isFinite(id) || !address) continue;
281	    out.push({
282	      id,
283	      address,
284	      goto: typeof o.goto === "string" ? o.goto : "",
285	      active: toActive(o.active),
286	      domain: typeof o.domain === "string" ? o.domain : undefined,
287	    });
288	  }
289	  return out;
290	}
291	
292	/**
293	 * Create an alias (`POST /add/alias`). `goto` is the destination address (or a
294	 * comma-separated list) mail to `address` should be delivered to. Throws a
295	 * MailcowError on any logical failure (e.g. the alias already exists).
296	 */
297	export async function mcAddAlias(address: string, goto: string): Promise<unknown> {
298	  return mcRequest("POST", "/add/alias", {
299	    address,
300	    goto,
301	    active: "1",
302	  });
303	}
304	
305	/** Delete an alias by its Mailcow id (`POST /delete/alias` with `[id]`). */
306	export async function mcDeleteAlias(id: number): Promise<unknown> {
307	  return mcRequest("POST", "/delete/alias", [id]);
308	}
309	
310	// ---------- Sieve filters (auto-reply + forwarding) ----------
311	
312	/**
313	 * A per-mailbox sieve filter as stored in Mailcow's `sieve_filters` table.
314	 *
315	 * Mailcow chains scripts as: global_sieve_before -> user `prefilter` ->
316	 * the user's own personal script -> user `postfilter` -> global_sieve_after.
317	 * Only ONE filter per (username, filter_type) can be active at a time —
318	 * Mailcow deactivates the others whenever a filter is added/edited as active.
319	 * That is why lib/mail/sieve.ts compiles auto-reply AND forwarding into a
320	 * single managed script instead of one filter each.
321	 */
322	export type MailcowFilter = {
323	  id: number;
324	  username: string;
325	  scriptDesc: string;
326	  scriptData: string;
327	  filterType: string; // "prefilter" | "postfilter"
328	  active: boolean;
329	};
330	
331	export type MailcowFilterType = "prefilter" | "postfilter";
332	
333	function toFilterRows(res: unknown): MailcowFilter[] {
334	  const rows = Array.isArray(res) ? res : [];
335	  const out: MailcowFilter[] = [];
336	  for (const r of rows) {
337	    if (!r || typeof r !== "object") continue;
338	    const o = r as Record<string, unknown>;
339	    const id = Number(o.id);
340	    if (!Number.isFinite(id)) continue;
341	    out.push({
342	      id,
343	      username: typeof o.username === "string" ? o.username : "",
344	      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
345	      scriptData: typeof o.script_data === "string" ? o.script_data : "",
346	      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
347	      active: toActive(o.active),
348	    });
349	  }
350	  return out;
351	}
352	
353	/**
354	 * List the sieve filters belonging to ONE mailbox
355	 * (`GET /get/filters/<address>`). Mailcow returns `{}` when there are none.
356	 *
357	 * Always pass a full address: `/get/filters/all` walks every domain on the
358	 * server, which would leak other tenants' scripts into our result.
359	 */
360	export async function mcListFilters(address: string): Promise<MailcowFilter[]> {
361	  const res = await mcRequest("GET", `/get/filters/${encodeURIComponent(address)}`);
362	  // Defence in depth: Mailcow scopes by username server-side, but we re-filter
363	  // so a wrong/greedy response can never hand one customer another's script.
364	  const want = address.trim().toLowerCase();
365	  return toFilterRows(res).filter((f) => f.username.trim().toLowerCase() === want);
366	}
367	
368	/** Create a sieve filter on a mailbox (`POST /add/filter`). */
369	export async function mcAddFilter(opts: {
370	  address: string;
371	  scriptDesc: string;
372	  scriptData: string;
373	  filterType: MailcowFilterType;
374	  active?: boolean;
375	}): Promise<unknown> {
376	  return mcRequest("POST", "/add/filter", {
377	    username: opts.address,
378	    script_desc: opts.scriptDesc,
379	    script_data: opts.scriptData,
380	    filter_type: opts.filterType,
381	    active: opts.active === false ? "0" : "1",
382	  });
383	}
384	
385	/**
386	 * Replace the body of an existing filter (`POST /edit/filter`).
387	 *
388	 * Mailcow keeps the current value for any field it receives EMPTY, so
389	 * `scriptData` must never be blank here — clearing a rule is a delete, not an
390	 * edit with an empty script.
391	 */
392	export async function mcEditFilter(
393	  id: number,
394	  attr: { scriptDesc: string; scriptData: string; filterType: MailcowFilterType; active?: boolean },
395	): Promise<unknown> {
396	  if (!attr.scriptData.trim()) {
397	    throw new MailcowError("Refusing to edit a sieve filter with an empty script — delete it instead.");
398	  }
399	  return mcRequest("POST", "/edit/filter", {
400	    items: [id],
401	    attr: {
402	      script_desc: attr.scriptDesc,
403	      script_data: attr.scriptData,
404	      filter_type: attr.filterType,
405	      active: attr.active === false ? "0" : "1",
406	    },
407	  });
408	}
409	
410	/** Delete a sieve filter by its Mailcow id (`POST /delete/filter`). */
411	export async function mcDeleteFilter(id: number): Promise<unknown> {
412	  return mcRequest("POST", "/delete/filter", [id]);
413	}
414	
415	// ---------- DKIM ----------
416	
417	/**
418	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
419	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
420	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
421	 * or null when the domain has no DKIM key yet or the shape is unexpected.
422	 *
423	 * Throws MailcowError only when the integration is unreachable/errors — callers
424	 * that must stay tolerant wrap this in try/catch.
425	 */
426	export async function mcGetDkim(domain: string): Promise<string | null> {
427	  return (await mcGetDkimDetails(domain))?.txt ?? null;
428	}
429	
430	/** The signing key Mailcow will actually use, plus the selector it publishes under. */
431	export type MailcowDkim = { selector: string; txt: string; bits: number | null };
432	
433	/**
434	 * Fetch the LIVE DKIM key + selector for a domain.
435	 *
436	 * The deliverability self-check must compare published DNS against this, never
437	 * against `EmailSubscription.dkimRecord`: that column is a cache written once at
438	 * DNS-setup time, so if the key is ever rotated (or the domain re-created on
439	 * Mailcow, which regenerates it) the cache silently describes a key that no
440	 * longer signs anything — and the check would tell a customer their DNS is
441	 * correct while every message they send fails DKIM.
442	 */
443	export async function mcGetDkimDetails(domain: string): Promise<MailcowDkim | null> {
444	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
445	  if (!res || typeof res !== "object") return null;
446	  // Mailcow returns {} for a domain with no key configured.
447	  const o = res as Record<string, unknown>;
448	  const txt = typeof o.dkim_txt === "string" ? o.dkim_txt.trim() : "";
449	  if (!txt) return null;
450	  const selector = typeof o.dkim_selector === "string" && o.dkim_selector.trim() ? o.dkim_selector.trim() : "dkim";
451	  const bits = Number(o.length);
452	  return { selector, txt, bits: Number.isFinite(bits) && bits > 0 ? bits : null };
453	}
