22	/**
23	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
24	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
25	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
26	 */
27	async function loadSmtp() {
28	  const rows = await db.setting.findMany({
29	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
30	  });
31	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
32	  const host = s.smtp_host || process.env.SMTP_HOST || "";
33	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
34	  return {
35	    host,
36	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
37	    user: s.smtp_user || process.env.SMTP_USER || "",
38	    pass: s.smtp_pass || process.env.SMTP_PASS || "",
39	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
40	    from,
41	  };
42	}
