102	export type SendMailOpts = {
103	  to: string;
104	  /** Explicit subject. Optional when `template` is provided. */
105	  subject?: string;
106	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
107	  html?: string;
108	  text?: string;
109	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
110	  template?: string;
111	  /** Variables for `{{placeholders}}` when rendering from a template. */
112	  vars?: Record<string, unknown>;
113	  /** Attribution for the EmailLog row. */
114	  userId?: string | null;
115	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
116	  invoiceId?: string;
117	  /** Extra attachments. */
118	  attachments?: MailAttachment[];
119	  /**
120	   * What KIND of message this is, for the notification-preference policy in
121	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
122	   * the customer's choice centrally — see the gate below.
123	   *
124	   * Omitting it means "always send", which is the safe default: a message must
125	   * never be dropped because someone forgot to classify it.
126	   */
127	  kind?: NotifyKind;
128	};
