130	/**
131	 * Send an email. Never throws — logs and returns false on failure so callers
132	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
133	 * FAILED + error otherwise) for the admin Logs viewer.
134	 *
135	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
136	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
137	 * turning off "email me about billing" changed nothing. Gating each send site
138	 * individually would have fixed today's sites and left every future one to
139	 * re-introduce the bug; gating centrally means a new send site inherits the
140	 * policy automatically and per-site checks become defence in depth.
141	 *
142	 * Two deliberate properties, both fail-open:
143	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
144	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
145	 *     the database, and also on a lookup error. A payment-failure or suspension
146	 *     warning must not be lost because a preference read failed.
147	 */
148	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
149	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
150	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
151	  // -circuit to true, so this costs nothing on the paths that matter most.
152	  if (opts.kind && opts.userId) {
153	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
154	    if (!allowed) {
155	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
156	      return false;
157	    }
158	  }
159	
160	  // Resolve subject/html: prefer explicit values, otherwise render the template.
161	  let subject = opts.subject ?? "";
162	  let html = opts.html ?? "";
163	  const templateKey = opts.template ?? null;
164	
165	  if (templateKey && !opts.html) {
166	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
167	    subject = opts.subject ?? rendered.subject;
168	    html = rendered.html;
169	  }
170	
171	  // Assemble attachments (invoice auto-attaches for the relevant templates).
172	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
173	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
174	  if (wantInvoice && opts.invoiceId) {
175	    const att = await invoiceAttachment(opts.invoiceId);
176	    if (att) attachments.push(att);
177	  }
178	
179	  try {
180	    const c = await loadSmtp();
181	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
182	      console.warn("[mailer] not configured — skipping email:", subject);
183	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
184	      return false;
185	    }
186	    const t = transport(c);
187	    await t.sendMail({
188	      from: c.from,
189	      to: opts.to,
190	      subject,
191	      html,
192	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
193	      attachments: attachments.length ? attachments : undefined,
194	    });
195	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
196	    return true;
197	  } catch (e) {
198	    console.error("[mailer] send failed:", e);
199	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
200	    return false;
201	  }
202	}
