/**
 * Send a transactional email without ever letting the mailer stall billing.
 * `sendMail` already logs every attempt to EmailLog and returns false rather than
 * throwing; this is the belt-and-braces so an SMTP surprise can't abort a sweep
 * halfway through a money decision.
 */
async function mail(
  to: string,
  userId: string,
  tpl: { template?: string; subject: string; html: string },
  // Classifies the message for the preference policy in lib/prefs.ts. DEFAULTS TO
  // A CRITICAL KIND on purpose: nearly every mail from this sweep is a payment
  // failure, a 3-D Secure prompt, a final notice or a suspension warning, and none
  // of those may ever be suppressed by a preference. Only the receipt is
  // ACCOUNT-tier, so only the receipt passes "receipt" explicitly. Getting the
  // default the other way round would risk silencing a suspension warning.
  kind: NotifyKind = "payment_failed"
) {
  try {
    await sendMail({ to, subject: tpl.subject, html: tpl.html, template: tpl.template, userId, kind });
  } catch (e) {
    console.error("[billing] email send failed", e);
  }
}

/** In-portal notice. Same never-throw contract as `mail` — bells are not money. */
async function notify(userId: string, title: string, body: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[billing] notification failed", e);
  }
}

