230	 * Subscribe one of the caller's registered domains to an email plan. Validates
231	 * domain ownership + plan availability, then atomically debits the wallet and
232	 * creates the EmailSubscription with an expiry set from the plan term.
233	 *
234	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
235	 * provisioned with a mail provider yet — that integration is pending, and the
236	 * UI surfaces every mailbox as "provisioning" until it lands.
237	 */
238	export async function orderEmailHosting(
239	  domainName: string,
240	  emailPlanId: string,
241	): Promise<Result> {
242	  const user = await requireUser();
243	  // Purchase gate: an unverified address means we cannot reach the person we
244	  // are about to charge. See lib/email-verification.ts.
245	  const unverified = await emailVerificationError(user);
246	  if (unverified) return { error: unverified };
247	
248	  const name = String(domainName ?? "")
249	    .trim()
250	    .toLowerCase()
251	    .replace(/\.$/, "");
252	  if (!name) return { error: "Enter a domain." };
253	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
254	
255	  // Is the domain registered inside Nxeon? If so we control its DNS and can
256	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
257	  // verified via DNS before mail flows.
258	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
259	  const external = !inAccount;
260	
261	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
262	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
263	
264	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
265	  //
266	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
267	  // which let anyone buy a subscription for a domain another customer already
268	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
269	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
270	  // ADDRESS — so an attacker could create admin@victim.com under their own
271	  // subscription, call resetMailboxPassword() (which passes its ownership check
272	  // because the row is theirs), and have the password of the victim's real, live
273	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
274	  const dupe = await db.emailSubscription.findFirst({
275	    where: { domainName: name, status: { not: "CANCELLED" } },
276	  });
277	  if (dupe) {
278	    return {
279	      error:
280	        dupe.userId === user.id
281	          ? "This domain already has an email subscription."
282	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
283	    };
284	  }
285	
286	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
287	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
288	  // strikethrough shown on the pricing page is the real renewal price and this
289	  // discounted value is the real first-term price — displayed === charged.
290	  const promo = currentPromo(new Date());
291	  const chargeCents = promoPriceCents(plan.priceCents, promo);
292	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
293	  if (user.balanceCents < chargeCents) {
294	    return { error: "Insufficient balance. Top up your wallet first." };
295	  }
296	
297	  try {
298	    await db.$transaction(async (tx) => {
299	      await debitWallet(tx, user.id, chargeCents);
300	      await tx.walletTransaction.create({
301	        data: {
302	          userId: user.id,
303	          amountCents: -chargeCents,
304	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
305	        },
306	      });
307	      await tx.emailSubscription.create({
308	        data: {
309	          userId: user.id,
310	          domainName: name,
311	          emailPlanId: plan.id,
312	          status: "ACTIVE",
313	          autoRenew: true,
314	          expiresAt: addMonths(new Date(), plan.termMonths),
315	          // In-account domains: we control DNS, so treat as verified now. External
316	          // domains: not verified until the customer publishes DNS + we confirm it.
317	          external,
318	          verified: !external,
319	          verifiedAt: external ? null : new Date(),
320	          verifyToken: external ? randomBytes(24).toString("hex") : null,
321	        },
322	      });
323	    });
324	  } catch (e) {
325	    if (e instanceof InsufficientBalanceError) {
326	      return { error: "Insufficient balance. Top up your wallet first." };
327	    }
328	    throw e;
329	  }
330	
331	  await db.auditLog.create({
332	    data: {
333	      userId: user.id,
334	      action: "emailhosting.order",
335	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
336	    },
337	  });
338	  revalidatePath("/dashboard/email");
339	  return { ok: true };
340	}
