import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import { mailAttachmentUrl } from "../lib/mail/types.ts";
import { emails } from "../lib/mailer.ts";
import {
  NOTIFY_KINDS,
  DEFAULT_PREFS,
  isSuppressible,
  mayDeliver,
  normalizePrefs,
  notifyTier,
  type NotifyKind,
  type NotificationPrefs,
} from "../lib/prefs.ts";

/**
 * Guards over the MAIL PLATFORM — the paid business-email product and the
 * transactional pipe every other feature sends through.
 *
 * Four defects live behind these assertions, and each one is the same shape:
 * a surface that reports an outcome nobody verified.
 *
 *   1. An attachment href that omitted the mailbox, so the download route
 *      re-resolved the account's DEFAULT mailbox and could return a different
 *      message's file.
 *   2. A template that promised an attached invoice the send site never attaches.
 *   3. A send wrapper that could not forward the message KIND, so nothing routed
 *      through it could ever honour the customer's email preference.
 *   4. Deliverability guidance that once named a mail host and an SPF include
 *      belonging to a domain this platform does not own.
 *
 * ── WHICH STRIPPER, AND WHY ──────────────────────────────────────────────────
 * `stripComments` keeps string contents, so it is what an assertion ABOUT A
 * VALUE uses ("is the MX still mail.nxeon.cloud?"). `stripCommentsAndStrings`
 * also blanks literals, so it is what an assertion about CODE SHAPE uses — this
 * repo narrates its own incidents in comments AND in error copy and audit-log
 * strings, so a naive grep for `mailAttachmentUrl` matches the paragraph
 * explaining why it exists.
 */

const ROOT = join(import.meta.dirname, "..");
const src = (rel: string) => readFileSync(join(ROOT, rel), "utf8");
/** Source with comments AND string contents removed — for code-shape assertions. */
const code = (rel: string) => stripCommentsAndStrings(src(rel));
/** Source with only comments removed — for assertions about a literal's value. */
const values = (rel: string) => stripComments(src(rel));

/* ========================================================================== *
 * 0. The stripper itself
 * ========================================================================== */

test("stripCommentsAndStrings blanks literals that a code-shape grep would match", () => {
  const sample = `
    // mailAttachmentUrl is described here
    const err = "call mailAttachmentUrl to build this";
    const detail = \`mailbox.suspend\`;
    realCall(mailAttachmentUrl);
  `;
  const stripped = stripCommentsAndStrings(sample);
  // Exactly one surviving mention: the real call.
  assert.equal(stripped.match(/mailAttachmentUrl/g)?.length, 1);
  assert.ok(!stripped.includes("mailbox.suspend"));
  assert.ok(stripped.includes("realCall(mailAttachmentUrl)"));
});

test("stripCommentsAndStrings keeps line numbers stable", () => {
  const sample = 'a\nconst s = `one\ntwo\nthree`;\nb\n';
  assert.equal(
    stripCommentsAndStrings(sample).split("\n").length,
    sample.split("\n").length,
  );
});

test("stripComments still preserves literals, so value assertions keep working", () => {
  const sample = 'const MAIL_HOST = "mail.nxeon.cloud"; // was mx.nxeon.email';
  const stripped = stripComments(sample);
  assert.ok(stripped.includes('"mail.nxeon.cloud"'));
  assert.ok(!stripped.includes("mx.nxeon.email"));
});

/* ========================================================================== *
 * 1. Attachment downloads resolve the mailbox they were rendered for
 * ========================================================================== */

test("mailAttachmentUrl carries the mailbox when one is known", () => {
  const url = mailAttachmentUrl({
    folder: "INBOX",
    uid: 41,
    part: "41:2",
    mailbox: "second@example.com",
  });
  const qs = new URL(url, "https://nxeon.cloud").searchParams;
  assert.equal(qs.get("mailbox"), "second@example.com");
  assert.equal(qs.get("folder"), "INBOX");
  assert.equal(qs.get("uid"), "41");
  assert.equal(qs.get("part"), "41:2");
});

test("mailAttachmentUrl omits the mailbox only when there genuinely isn't one", () => {
  const url = mailAttachmentUrl({ folder: "INBOX", uid: 7, part: "2" });
  assert.ok(!new URL(url, "https://nxeon.cloud").searchParams.has("mailbox"));
});

test("mailAttachmentUrl escapes folder names and addresses", () => {
  // A folder with a space and an ampersand, and an address with a plus tag,
  // must survive intact — a hand-rolled template string got this wrong for
  // `part` once already.
  const url = mailAttachmentUrl({
    folder: "Archive/R&D notes",
    uid: 3,
    part: "3:1.2",
    mailbox: "sales+eu@example.com",
  });
  assert.ok(!url.slice(url.indexOf("?")).includes(" "));
  const qs = new URL(url, "https://nxeon.cloud").searchParams;
  assert.equal(qs.get("folder"), "Archive/R&D notes");
  assert.equal(qs.get("mailbox"), "sales+eu@example.com");
  assert.equal(qs.get("part"), "3:1.2");
});

test("the reading pane builds attachment links through mailAttachmentUrl", () => {
  const pane = code("components/customer/mail/ReadingPane.tsx");
  assert.match(
    pane,
    /mailAttachmentUrl\s*\(/,
    "ReadingPane must build attachment hrefs with mailAttachmentUrl",
  );
  assert.match(
    pane,
    /mailbox:\s*mailboxAddress/,
    "ReadingPane must pass the active mailbox into the attachment URL",
  );
  // A hand-built href is how the mailbox got dropped in the first place. The
  // path only survives inside `mailAttachmentUrl`, so after stripping literals
  // it must not appear here at all.
  assert.ok(
    !pane.includes("/api/mail/attachment"),
    "ReadingPane must not hand-build the attachment path",
  );
});

test("MailClient hands the active mailbox to the reading pane", () => {
  const client = code("components/customer/mail/MailClient.tsx");
  assert.match(
    client,
    /mailboxAddress=\{activeAddress\}/,
    "MailClient must pass activeAddress down as mailboxAddress",
  );
});

test("the attachment route still resolves ownership from the mailbox parameter", () => {
  const route = code("app/api/mail/attachment/route.ts");
  assert.match(route, /resolveMailbox\s*\(\s*mailbox\s*\)/);
  assert.match(route, /sp\.get\(\s*\)/, "the route must read the mailbox query parameter");
});

/* ========================================================================== *
 * 2. Templates claim only what the send site does
 * ========================================================================== */

const INVOICE_ARGS = {
  invoiceNumber: "00042",
  amount: "$24.00",
  dueDate: "Aug 1, 2026",
  description: "VPS Nebula — 1 month",
