/* ========================================================================== *
 * 4. Notification tiering is correct in BOTH directions
 * ========================================================================== */

/**
 * Messages a customer must receive whatever they ticked. Suppressing any of
 * these is how someone loses a server, an account, or their data with no
 * warning — strictly worse than the "column nobody read" bug this policy fixed.
 */
const MUST_ALWAYS_ARRIVE: NotifyKind[] = [
  "password_reset",
  "email_verify",
  "security_change",
  "payment_failed",
  "payment_action_required",
  "card_expiring",
  "expiry_warning",
  "suspension",
  "termination",
  "abuse",
  "data_loss",
  "fulfilment_failed",
  "refund",
];

const OPTED_OUT: NotificationPrefs = { email: false, product: false, security: true };

test("nothing a customer must see is suppressible, on any channel", () => {
  for (const kind of MUST_ALWAYS_ARRIVE) {
    assert.equal(notifyTier(kind), "CRITICAL", `${kind} must be CRITICAL`);
    for (const channel of ["email", "inapp"] as const) {
      assert.equal(isSuppressible(kind, channel), false, `${kind}/${channel}`);
      assert.equal(mayDeliver(OPTED_OUT, kind, channel), true, `${kind}/${channel}`);
    }
  }
});

test("the account-email toggle actually suppresses account email", () => {
  // The other direction: a toggle that suppresses nothing is the original bug.
  for (const kind of ["receipt", "welcome", "invoice", "job_done"] as NotifyKind[]) {
    assert.equal(notifyTier(kind), "ACCOUNT", `${kind} must be ACCOUNT`);
    assert.equal(mayDeliver(OPTED_OUT, kind, "email"), false, `${kind} email`);
    // …but the in-app record survives, so the information is never simply lost.
    assert.equal(mayDeliver(OPTED_OUT, kind, "inapp"), true, `${kind} inapp`);
  }
});

test("marketing is suppressible on every channel, and only by its own flag", () => {
  assert.equal(mayDeliver(OPTED_OUT, "product_news", "email"), false);
  assert.equal(mayDeliver(OPTED_OUT, "product_news", "inapp"), false);
  // Turning OFF account email must not silence product news, and vice versa —
  // one checkbox governing two lists is how consent gets lost by accident.
  assert.equal(
    mayDeliver({ email: false, product: true, security: true }, "product_news", "email"),
    true,
  );
  assert.equal(
    mayDeliver({ email: true, product: false, security: true }, "receipt", "email"),
    true,
  );
});

test("every declared kind has a tier, and an undeclared one fails towards delivery", () => {
  for (const [kind, tier] of Object.entries(NOTIFY_KINDS)) {
    assert.ok(["CRITICAL", "ACCOUNT", "PRODUCT"].includes(tier), `${kind} → ${tier}`);
    assert.equal(notifyTier(kind as NotifyKind), tier);
  }
  // A typo'd or forgotten kind must be delivered, never dropped.
  assert.equal(notifyTier("not_a_real_kind" as NotifyKind), "CRITICAL");
  assert.equal(mayDeliver(OPTED_OUT, "not_a_real_kind" as NotifyKind, "email"), true);
});

test("absent or malformed stored prefs read as opted IN, and security stays pinned", () => {
  assert.deepEqual(normalizePrefs(null), DEFAULT_PREFS);
  assert.deepEqual(normalizePrefs({}), DEFAULT_PREFS);
  assert.deepEqual(normalizePrefs({ email: "no" }), DEFAULT_PREFS);
  // A stored withdrawal of security consent must not round-trip.
  assert.equal(normalizePrefs({ security: false }).security, true);
  assert.equal(normalizePrefs({ email: false }).email, false);
});

/* ========================================================================== *
 * 5. Deliverability guidance matches the mail server we actually run
 * ========================================================================== */
//
// Verified read-only against the live estate on 2026-07-27:
//   Mailcow  GET /get/dkim/nxeon.cloud  -> dkim_selector "dkim", 2048-bit key
//   1.1.1.1  MX nxeon.cloud             -> 10 mail.nxeon.cloud
//   1.1.1.1  A  mail.nxeon.cloud        -> 51.79.162.96
//   1.1.1.1  TXT nxeon.cloud            -> "v=spf1 mx ~all"  (so `include:
//                                           nxeon.cloud` authorises that A)
// The values below are what the product prints on a customer's DNS panel, so a
// silent edit here mis-routes or unauthenticates every customer domain at once.

test("customers are told to point MX at the mail host Mailcow actually serves", () => {
  const hosting = values("lib/actions-email-hosting.ts");
  assert.match(hosting, /const MAIL_HOST = "mail\.nxeon\.cloud"/);
  assert.match(hosting, /const SPF_INCLUDE = "nxeon\.cloud"/);
  assert.match(hosting, /const SPF_VALUE = `v=spf1 include:\$\{SPF_INCLUDE\} ~all`/);
});

test("the retired nxeon.email host and _spf include are gone from executable code", () => {
  // They survive in incident notes on purpose, which is why comments are
  // stripped rather than the raw file being grepped.
  for (const file of [
    "lib/actions-email-hosting.ts",
    "lib/mail/deliverability.ts",
    "lib/settings.ts",
    "components/customer/EmailHosting.tsx",
    "components/customer/mail/MailSettings.tsx",
  ]) {
    const stripped = values(file);
    assert.ok(!stripped.includes("nxeon.email"), `${file} still names nxeon.email`);
    assert.ok(!stripped.includes("_spf.nxeon"), `${file} still names _spf.nxeon`);
  }
});

test("the webmail UI names the same host it tells customers to point MX at", () => {
  assert.match(values("components/customer/EmailHosting.tsx"), /const WEBMAIL_HOST = "mail\.nxeon\.cloud"/);
  assert.match(values("components/customer/mail/MailSettings.tsx"), /const MAIL_HOST = "mail\.nxeon\.cloud"/);
});

test("the DKIM check reads the LIVE key, never the cached column", () => {
  // `EmailSubscription.dkimRecord` is a cache written once at setup. Comparing
  // DNS against it would confirm a key that no longer signs anything — the
  // check would tell a customer their mail is authenticated while every message
  // fails DKIM. Mailcow's selector is `dkim`; the fallback must match it.
  const deliverability = code("lib/mail/deliverability.ts");
  assert.ok(
    !deliverability.includes("dkimRecord"),
    "the deliverability check must not read the cached dkimRecord column",
  );
  const hosting = code("lib/actions-email-hosting.ts");
  assert.match(
    hosting,
    /mcGetDkimDetails/,
    "the check's caller must fetch the live key from Mailcow",
  );
  assert.match(values("lib/mail/deliverability.ts"), /opts\.dkim\?\.selector \|\| "dkim"/);
});

