test("every mail server action resolves the mailbox through the ownership check", () => {
  const actions = code("lib/actions-mail.ts");
  // Each exported action must resolve a mailbox the caller owns before it can
  // reach IMAP. `getMailboxes` scopes its own query by userId instead.
  const exported = [...actions.matchAll(/export async function (\w+)/g)].map((m) => m[1]);
  assert.ok(exported.length >= 7, `expected the full action surface, saw ${exported.length}`);
  for (const name of exported) {
    const start = actions.indexOf(`export async function ${name}`);
    const next = actions.indexOf("export async function ", start + 1);
    const body = actions.slice(start, next === -1 ? undefined : next);
    assert.match(
      body,
      /resolveMailbox\(|subscription:\s*\{\s*userId:\s*user\.id\s*\}/,
      `${name} must scope to a mailbox the caller owns`,
    );
  }
});

