test("auto-reply and forwarding reach Mailcow BEFORE the database is written", () => {
  // This ordering is the whole fix for the store-only bug: if the push fails the
  // row is left alone and the customer sees the failure, instead of a "Saved"
  // over a mail server that changed nothing.
  const settings = code("lib/actions-mailbox-settings.ts");
  for (const fnName of ["saveForwarding", "saveAutoReply"]) {
    const start = settings.indexOf(`export async function ${fnName}`);
    const body = settings.slice(start, settings.indexOf("export async function ", start + 1));
    const push = body.indexOf("pushMailboxSieve");
    const write = body.indexOf("db.mailbox.update");
    assert.ok(push > -1, `${fnName} must push sieve to Mailcow`);
    assert.ok(write > -1, `${fnName} must persist`);
    assert.ok(push < write, `${fnName} must push to Mailcow before writing the DB`);
    assert.match(body, /catch \(e\)[\s\S]{0,200}return \{ ok: false/, `${fnName} must surface a push failure`);
  }
});

test("the live rule status is read back from Mailcow, not inferred from the DB", () => {
