/* ========================================================================== *
 * 8. The unauthenticated signature-image route stays narrow
 * ========================================================================== */

test("the public signature-image route is keyed by an unguessable id", () => {
  // It is fetched by recipients' mail clients, which have no session — so the
  // id being a cuid, not a sequential integer, IS the access control.
  const schema = values("prisma/schema.prisma");
  const model = schema.slice(schema.indexOf("model SignatureImage"));
  const body = model.slice(0, model.indexOf("}"));
  assert.match(body, /id\s+String\s+@id\s+@default\(cuid\(\)\)/);
  assert.ok(!/@default\(autoincrement\(\)\)/.test(body), "an enumerable id would expose every image");
});

test("the public signature-image route returns image bytes and nothing else", () => {
  const route = code("app/api/mail/signature-image/[id]/route.ts");
  // Only two columns may leave: the bytes and their type. Never the owner.
  assert.match(route, /select:\s*\{\s*mime:\s*true,\s*data:\s*true,?\s*\}/);
  assert.ok(!route.includes("userId"), "the route must not select or expose the owner");
  // Defence in depth for a mime that somehow got past the upload validator.
  assert.match(route, /isAllowedImageMime\(image\.mime\)/);
  const headers = values("app/api/mail/signature-image/[id]/route.ts");
  assert.match(headers, /"X-Content-Type-Options": "nosniff"/);
  assert.match(headers, /"Content-Security-Policy": "default-src 'none'; sandbox"/);
  assert.match(headers, /"Content-Disposition": 'inline/);
});

test("uploading a signature image requires a session and is capped per account", () => {
  const route = code("app/api/mail/signature-image/route.ts");
  assert.match(route, /requireUser\(\)/);
  // Keyed on the account alone: a forged X-Forwarded-For must not mint a bucket.
  assert.match(route, /checkRateLimit\(\s*,\s*\{ max: 15/);
  assert.ok(!route.includes("clientIp"), "the limiter must not key on a caller-supplied IP");
  assert.match(route, /validateImageBytes\(bytes, file\.type\)/);
});

test("no other route under app/api/mail is reachable without a session", () => {
  const attachment = code("app/api/mail/attachment/route.ts");
  assert.match(attachment, /resolveMailbox\(/);
  const upload = code("app/api/mail/signature-image/route.ts");
  assert.match(upload, /requireUser\(\)/);
});

