test("webmail IMAP and SMTP verify the mail server's certificate", () => {
  // `rejectUnauthorized: false` accepts ANY certificate, and the first thing
  // these sessions send is the customer's mailbox password.
  for (const file of ["lib/mail/imap.ts", "lib/actions-mail.ts"]) {
    const stripped = code(file);
